INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0971', '転生したら第七王子だったので、気ままに魔術を極めます', '2024年春', 'PR0038', 'TVシリーズ', 12, '『転生したら第七王子だったので、気ままに魔術を極めます』（てんせいしたらだいななおうじだったので、きままにまじゅつをきわめます）は、謙虚なサークルによる日本のライトノベル作品。「小説家になろう」にて2019年10月より連載されており、書籍版は講談社ラノベ文庫（講談社）より2020年7月から刊行されている。イラストはメル。が担当している。略称は「第七王子」。 メディアミックスとして、石沢庸介によるコ', 156415) ON CONFLICT DO NOTHING;
