INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0991', '怪異と乙女と神隠し', '2024年春', 'PR0059', 'TVシリーズ', 12, '『怪異と乙女と神隠し』（かいいとおとめとかみかくし）は、ぬじまによる日本の漫画作品。「やわらかスピリッツ」（小学館）にて、2019年10月18日から連載中。2024年4月から6月までテレビアニメが放送された。', 160090) ON CONFLICT DO NOTHING;
