INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0998', 'ワンルーム、日当たり普通、天使つき。', '2024年春', 'PR0013', 'TVシリーズ', 12, '『ワンルーム、日当たり普通、天使つき。』（ワンルーム ひあたりふつう てんしつき）は、matobaによる日本の漫画作品。『月刊少年ガンガン』（スクウェア・エニックス）にて、2020年10月号より2025年4月号まで連載。マンションで一人暮らしをする男子高校生の元にやってきた天使と同居する様子を描くラブコメディ。 2021年4月に単行本第1巻が発売された際には、YouTubeにてPVを公開。 202', 169927) ON CONFLICT DO NOTHING;
