INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1002', '声優ラジオのウラオモテ', '2024年春', 'PR0064', 'TVシリーズ', 12, '『声優ラジオのウラオモテ』（せいゆうラジオのウラオモテ）は、二月公による日本のライトノベル。イラスト担当はさばみぞれ（本編）と巻本梅実（スピンオフ）。電撃文庫（KADOKAWA）より2020年2月から刊行されている。2026年6月刊行の第15巻で完結と銘打たれているが、翌7月より電子書籍で続刊されることが発表されている。 本作は、2019年に行われた第26回電撃小説大賞の大賞受賞作品である。202', 159039) ON CONFLICT DO NOTHING;
