INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1008', 'アストロノオト', '2024年春', 'PR0066', 'TVシリーズ', 12, '『アストロノオト』（Astro Note）は、テレコム・アニメーションフィルム制作による日本のテレビアニメ。2024年4月から6月までTOKYO MXほかにて放送された。 木造アパート・あすトろ荘の大家であるミラと、住み込み料理人・拓己のSFラブコメディ。総監督は高松信司、監督は春日森春木、シリーズ構成はうえのきみこが担当する。', 171040) ON CONFLICT DO NOTHING;
