INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1021', '杖と剣のウィストリア', '2024年夏', 'PR0073', 'TVシリーズ', 12, '『杖と剣のウィストリア』（つえとつるぎのウィストリア）は、大森藤ノ（原作）、青井聖（作画）による日本の漫画作品。『別冊少年マガジン』（講談社）にて2021年1月号から連載中。 魔法を使えないが強い力と卓越した剣技を持つ主人公が、幼き日の約束を果たすため、魔法絶対至上主義の世界で塔の頂を目指すファンタジー。 連載開始時には松岡禎丞が声を担当するPVが公開された。2026年1月時点で部数が300万部を', 174576) ON CONFLICT DO NOTHING;
