INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004386', 'AN0950', '望', '望（のぞみ、のぞむ、もち、ぼう、まどか）は、女性名と男性名（Nozomi、Nozomu、Bou、Mochi）。又は日本の女性名と男性名。また、満月のことを古くは望と呼ぶ。', NULL, '女性', 60287) ON CONFLICT DO NOTHING;
