INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004390', 'AN0950', 'ルパ', 'ルパ（lupa）はラテン語で狼をいうlupusの女性形でメスの狼をいう。  古代ローマの伝説でロームルスとレムスを育てたという狼。 売春婦、売女 ルパ（repas）はフランス語で「食事」の意味。（fr:Repas）  （Le repasで）京王食品（京王グループ）が運営するベーカリーショップ', NULL, '男性', 60055) ON CONFLICT DO NOTHING;
