INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004481', 'AN0953', 'ジョシュア', 'ジョシュア (Joshua) は英語圏の人名。短縮形でジョシュ (Josh) ともいう。 旧約聖書にしばしば登場する名前であるヨシュアの英語形で、近代以前にはユダヤ系の人物に多かったが、現在ではそのようなことはなく、アメリカ合衆国社会保障局の調査によれば2000年代には3番目に多い男性名であった。ドイツ語: Josua、イタリア語: Josué、スペイン語: Josué、ポルトガル語: Josué', NULL, '女性', 324271) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004482', 'AN0953', 'アレックス', 'アレックス（Alex） ギリシア語の人名「アレクサンドロス」に由来するヨーロッパの名（ファーストネームまたはミドルネーム）あるいは姓。 ドイツ語圏における「アレクサンダー」やロシア語における「アレクサンドル」および「アレクセイ」、イタリア語圏およびブラジルにおける「アレッサンドロ」とその女性形である「アレクサンドラ」、あるいはしばしば地名となる「アレクサンドリア」などの短縮型である。 英語での発音', NULL, '男性', 324288) ON CONFLICT DO NOTHING;
