INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004582', 'AN0958', '大久保利通', '大久保 利通（おおくぼ としみち、文政13年8月10日〈1830年9月26日〉- 明治11年〈1878年〉5月14日）は、日本の政治家、武士（旧薩摩藩士）。幼名は正袈裟、通称は正助、一蔵、諱は利済、のち利通、号は甲東。位階・勲等は贈従一位勲一等。 明治維新の元勲であり、西郷隆盛、木戸孝允と並んで「維新の三傑」と称され、「維新の十傑」のひとりでもある。初代内務卿で、内閣制度発足前の日本国政府（太政官', NULL, '男性', 326270) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004583', 'AN0958', '川路利良', '川路 利良（かわじ としよし、天保5年5月11日（1834年6月17日） - 明治12年（1879年）10月13日）は、日本の警察官・陸軍軍人。幕末から明治初期の薩摩藩士、内務官僚。階級は大警視（後に旧警視長を経て現在の警視総監）、陸軍少将（臨時）。位階は正五位。勲等は勲二等。 初代大警視（現・警視総監）を務め、欧米の近代警察制度を日本で初めて詳細に構築した事実上日本の警察の創設者にして、「日本警', NULL, '男性', 326263) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004584', 'AN0958', '武市熊吉', NULL, NULL, '男性', 326271) ON CONFLICT DO NOTHING;
