INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004662', 'AN0961', 'サブロー', 'サブロー（本名：大村 三郎〈おおむら さぶろう〉、1976年6月1日 - ）は、岡山県岡山市北区出身の元プロ野球選手（外野手、右投右打）、プロ野球監督。 現役時代は1995年から2016年まで22年間、ほぼ千葉ロッテマリーンズ一筋でプレーし、引退後は二軍監督、一軍ヘッドコーチを務めた。2026年シーズンからは一軍監督に就任。 妻はタレントの中嶋ミチヨ（2000年8月結婚）。', NULL, NULL, 314932) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004663', 'AN0961', 'ジロー・田中', NULL, 10, '男性', 314930) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004664', 'AN0961', 'ゴロー・佐藤', NULL, 18, '男性', 314931) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004665', 'AN0961', 'ナンシー', 'ナンシー（フランス語: Nancy）はフランス北部、グラン・テスト地域圏の都市である。ムルト＝エ＝モゼル県の県庁所在地。近隣の都市としては、約45キロ北にメスが位置する。鉄鋼業で有名。', NULL, '女性', 320040) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004666', 'AN0961', 'ソテツ', 'ソテツ（蘇鉄、蘓鉄、学名: Cycas revoluta）は、裸子植物のソテツ目、ソテツ科、ソテツ属に属する常緑樹の1種である。幹の頂端に大きな葉が多数密生する（図1）。外観はヤシや木生シダに似ているが、系統的には全く遠縁であり、この類似性は他人のそら似である。幹は、枯れ落ちた葉の基部が残ってうろこ状に覆われている。雌雄異株であり、雄株は細長い円柱状の小胞子嚢穂（"雄花"）を、雌株は大胞子葉が密生', NULL, '男性', 326930) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004667', 'AN0961', 'スコット', 'スコット', NULL, '男性', 326938) ON CONFLICT DO NOTHING;
