INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004782', 'AN0965', '銀子', '銀子（ぎんこ）  筋子-サケ科魚類の卵。 徳田秋声の小説『縮図』に登場する主人公。 銀子（ぎんす）  銀貨に対する江戸時代以前の古い呼称。 極印灰吹銀 石州銀 丁銀', NULL, '女性', 304323) ON CONFLICT DO NOTHING;
