INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH004784', 'AN0965', '須磨', '須磨（すま）は、摂津国の地名。現在の兵庫県神戸市須磨区にあたる。瀬戸内海を臨む須磨の浦で名高い白砂青松の景勝地。歌枕。  須磨区 - 兵庫県神戸市西部に位置する区。 艦船名 須磨 (防護巡洋艦) - 日本海軍の防護巡洋艦。 須磨 (砲艦) - 日本海軍の砲艦。 すま (特務艇) - 海上自衛隊の曳船、特務艇。元アメリカ海軍港内曳船「YTL-749」。 すま (海洋観測艦) - 海上自衛隊の海洋観測', 19, '女性', 250555) ON CONFLICT DO NOTHING;
