INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005035', 'AN0971', 'グリモワール', 'グリモワール（仏: grimoire、仏語発音: [ɡrimwar]）とは、フランス語で魔術の書物を意味し、特にヨーロッパで流布した魔術書を指す。グリモワ、グリモアとも表記される。奥義書、魔導書（魔道書）、魔法書ともいう。類義語に黒本、黒書（black books）がある。', NULL, '男性', 290878) ON CONFLICT DO NOTHING;
