INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005846', 'AN1012', '秋田藤四郎', '秋田藤四郎（あきたとうしろう）は、鎌倉時代に作られたとされる日本刀（短刀）。日本の重要文化財に指定されており、京都市東山区にある京都国立博物館が所蔵する。', NULL, '男性', 140473) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005847', 'AN1012', '平野藤四郎', '平野藤四郎（ひらのとうしろう）は、鎌倉時代に作られたとされる日本刀（短刀）。皇室の私有財産（御物）であり、宮内庁侍従職が管理している。', NULL, '男性', 140481) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005848', 'AN1012', '五虎退', '五虎退（ごこたい）あるいは五虎逃げ（ごこにげ）は、鎌倉時代に作られたとされる日本刀（短刀）。日本の重要美術品に認定されており、2019年時点では個人所蔵で米沢市上杉博物館に寄託されている。1937年の重要美術品認定時の名称は「短刀 銘吉光 附 腰刀拵（柄ナシ）」。五鈷吉光は誤記であることを刀剣研究家の福永酔剣は指摘している。', NULL, '男性', 140474) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005849', 'AN1012', '蛍丸', '蛍丸（ほたるまる）は、鎌倉時代に作られたとされる日本刀（大太刀）である。阿蘇神社に保管されたことから阿蘇の蛍丸とも呼ばれる。1931年に旧国宝に指定されたが、太平洋戦争終戦時の混乱により行方不明となっている。', NULL, '男性', 89810) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005850', 'AN1012', '弥助', '弥助（やすけ、生没年不詳）は、安土桃山時代の日本に渡来した黒人男性。宣教師から織田信長へと進呈され、信長が死去するまでの約15か月間、彼に仕えた。名は弥介（彌介）とも書かれる。', NULL, '男性', 335880) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005851', 'AN1012', '同田貫正国', NULL, NULL, '男性', 140475) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005852', 'AN1012', '大倶利伽羅', NULL, NULL, '男性', 140500) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005853', 'AN1012', '愛染国俊', '愛染国俊（あいぜんくにとし）は、鎌倉時代に作られたとされる日本刀（短刀）。日本の重要文化財に指定されており、大阪府茨木市にある法人が所蔵する。', NULL, '男性', 140472) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005854', 'AN1012', '小狐丸', '小狐丸（こぎつねまる）は、平安時代に作られたとされる日本刀（太刀）である。同名複数の刀剣が存在するが、本項では三条宗近作と言い伝えられている日本刀を中心に説明する。', NULL, '男性', 89806) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005855', 'AN1012', '審神者', '審神者（さにわ、歴史的仮名遣いでは「さには」）とは、古代の神道の祭祀において神託を受け、神意を解釈して伝える者のことである。 元は「清庭」（さやにわ）の意味で、神を祭り神託を受けるために斎み清められた庭（場所）のことを指す語であった。そこから転じて、同所で神託を受ける者の称ともとなった。 『古事記』の仲哀天皇の段に、天皇が琴を弾き、武内宿禰が沙庭（さにわ）に居て神の命を請うたという記述がある。ここ', NULL, NULL, 335863) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005856', 'AN1012', '斎藤利三', NULL, NULL, '男性', 335881) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005857', 'AN1012', '蜂須賀虎徹', NULL, NULL, '男性', 140478) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH005858', 'AN1012', '乱藤四郎', NULL, NULL, '男性', 140494) ON CONFLICT DO NOTHING;
