INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006250', 'AN1028', '高師直', '高 師直（こう の もろなお）は、鎌倉時代末期から南北朝時代にかけて足利尊氏に側近として仕えた武将、官僚、政治家、歌人。正式な名乗りは、高階 師直（たかしな の もろなお）。 高師重の子、兄弟に師泰・重茂、子に師夏・師詮ら。鎌倉幕府有力御家人足利氏執事（家宰）、建武政権雑訴決断所三番奉行人・武者所および窪所寄人、北朝武蔵守、室町幕府初代および第三代執事（室町幕府管領の前身）・上総国守護・武蔵国守護', NULL, '男性', 339813) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006251', 'AN1028', '五大院宗繁', NULL, NULL, '男性', 340793) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006252', 'AN1028', '市河助房', '市河 助房（いちかわ すけふさ）は、鎌倉時代末期から南北朝時代の武将。', NULL, '男性', 349878) ON CONFLICT DO NOTHING;
