INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006256', 'AN1028', '摂津親鑑', '摂津 親鑑（せっつ の ちかあき/ちかみ）は、鎌倉時代末期の武士・吏僚。北条氏得宗家被官である御内人。旧字体は摂津親鑒。', NULL, '男性', 339815) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006257', 'AN1028', '小笠原貞宗', NULL, NULL, '男性', 300901) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006258', 'AN1028', '後醍醐天皇', '後醍醐天皇（ごだいごてんのう、1288年11月26日〈正応元年11月2日〉 - 1339年9月19日〈延元4年/暦応2年8月16日〉）は、日本の第96代天皇、および南朝初代天皇（在位:1318年3月29日〈文保2年2月26日〉 - 1339年9月18日〈延元4年/暦応2年8月15日〉、治天:1321年12月28日〈元亨元年12月9日〉 - 1339年9月18日〈延元4年/暦応2年8月15日〉）。諱', NULL, '男性', 350262) ON CONFLICT DO NOTHING;
