INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH006262', 'AN1028', '長崎高資', '長崎 高資（ながさき たかすけ）は、鎌倉時代末期の武士。北条氏得宗家の被官である御内人・内管領。長崎円喜の嫡男。鎌倉幕府の実権を握って父と共に権勢を振るった。', NULL, '男性', 339817) ON CONFLICT DO NOTHING;
